// https://patrickjaillet.github.io/BS_shadertoy/
#define VITESSE_ANIMATION 2.5
#define DISTANCE_MAX       120.0
#define SEUIL_COLLISION    0.002
#define MAX_ETAPES         100

#define ROT(a) mat2(cos(a), -sin(a), sin(a), cos(a))

float aleatoire(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453123);
}

float bruit(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);

    float a = aleatoire(i);
    float b = aleatoire(i + vec2(1.0, 0.0));
    float c = aleatoire(i + vec2(0.0, 1.0));
    float d = aleatoire(i + vec2(1.0, 1.0));

    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float bruitFractal(vec2 p) {
    float valeur = 0.0;
    float amplitude = 0.5;
    mat2 rot = ROT(0.5);

    for (int i = 0; i < 3; i++) {
        valeur += amplitude * bruit(p);
        p = rot * p * 2.05;
        amplitude *= 0.48;
    }
    return valeur;
}

float carteHauteurDunes(vec2 position) {
    position *= 0.12;
    float hauteur = 0.0;
    float poids = 1.0;

    for (int i = 0; i < 3; i++) {
        float vague = sin(position.x * 0.7 + position.y * 0.5 + bruitFractal(position * 0.8) * 1.8);
        vague = 1.0 - abs(vague);
        vague = pow(vague, 2.2);
        hauteur += vague * poids;
        position = ROT(1.3) * position * 1.85;
        poids *= 0.42;
    }
    return hauteur * 3.8;
}

vec3 calculerNormale(vec3 p) {
    vec2 decalage = vec2(0.015, 0.0);
    return normalize(vec3(
        carteHauteurDunes(p.xz - decalage.xy) - carteHauteurDunes(p.xz + decalage.xy),
        2.0 * decalage.x,
        carteHauteurDunes(p.xz - decalage.yx) - carteHauteurDunes(p.xz + decalage.yx)
    ));
}

vec3 couleurCiel(vec3 rayonDirection, vec3 directionSoleil) {
    float alignementSoleil = max(dot(rayonDirection, directionSoleil), 0.0);

    vec3 couleurFond = mix(
        vec3(0.95, 0.55, 0.25), 
        vec3(0.40, 0.60, 0.85), 
        clamp(rayonDirection.y * 2.0 + 0.2, 0.0, 1.0)
    );

    couleurFond = mix(couleurFond, vec3(1.0, 0.75, 0.40), pow(alignementSoleil, 4.0));
    couleurFond += vec3(1.0, 0.80, 0.50) * pow(alignementSoleil, 128.0) * 1.5;

    return couleurFond;
}

void mainImage(out vec4 couleurFragment, in vec2 coordonneesFragment) {
    vec2 uv = (coordonneesFragment - 0.5 * iResolution.xy) / iResolution.y;

    float intensiteChaleur = smoothstep(0.3, -0.4, uv.y);
    float bruitA = bruit(uv * 25.0 + vec2(iTime * 1.5, iTime * 4.0));
    float bruitB = bruit(uv * 40.0 - vec2(iTime * 3.0, iTime * 2.0));
    vec2 distortion = vec2(bruitA - 0.5, bruitB - 0.5) * 0.018 * intensiteChaleur;
    uv += distortion;

    vec3 origineCamera = vec3(0.0, 7.5, iTime * VITESSE_ANIMATION);
    vec3 cibleCamera   = origineCamera + vec3(0.0, -0.65, 1.0);

    vec3 axeZ = normalize(cibleCamera - origineCamera);
    vec3 axeX = normalize(cross(vec3(0.0, 1.0, 0.0), axeZ));
    vec3 axeY = cross(axeZ, axeX);
    vec3 rayonDirection = normalize(uv.x * axeX + uv.y * axeY + 1.2 * axeZ);

    vec3 directionSoleil = normalize(vec3(0.6, 0.25, 0.8));

    float distanceParcourue = 0.1;
    bool collisionDetected = false;
    vec3 pointImpact = origineCamera;

    for (int i = 0; i < MAX_ETAPES; i++) {
        pointImpact = origineCamera + rayonDirection * distanceParcourue;
        float hauteurEchantillon = carteHauteurDunes(pointImpact.xz);
        float ecartHauteur = pointImpact.y - hauteurEchantillon;

        if (ecartHauteur < SEUIL_COLLISION * distanceParcourue) {
            collisionDetected = true;
            break;
        }

        distanceParcourue += ecartHauteur * 0.4;
        if (distanceParcourue > DISTANCE_MAX) break;
    }

    vec3 couleurFinal = vec3(0.0);

    if (collisionDetected) {
        vec3 normaleSurface = calculerNormale(pointImpact);

        float grainSable = bruitFractal(pointImpact.xz * 15.0);
        normaleSurface = normalize(normaleSurface + vec3(grainSable * 0.1, 0.0, grainSable * 0.1));

        float luminositeDirecte = max(dot(normaleSurface, directionSoleil), 0.0);
        float lumEclairageAmbiant = clamp(0.5 + 0.5 * normaleSurface.y, 0.0, 1.0);
        float lumRetroEclairage = max(dot(normaleSurface, normalize(vec3(-directionSoleil.x, 0.0, -directionSoleil.z))), 0.0);

        vec3 couleurSable     = vec3(0.92, 0.58, 0.28);
        vec3 couleurOmbre     = vec3(0.35, 0.25, 0.35);

        couleurFinal = couleurSable * luminositeDirecte * vec3(1.1, 0.9, 0.7);
        couleurFinal += couleurSable * lumEclairageAmbiant * couleurOmbre;
        couleurFinal += couleurSable * lumRetroEclairage * vec3(0.4, 0.2, 0.1);

        vec3 demiVecteur = normalize(directionSoleil - rayonDirection);
        float speculaire = pow(max(dot(normaleSurface, demiVecteur), 0.0), 32.0);
        couleurFinal += vec3(1.0, 0.8, 0.6) * speculaire * luminositeDirecte * 0.4;

        float facteurBrouillard = 1.0 - exp(-distanceParcourue * 0.025);
        vec3 couleurBrouillard = couleurCiel(rayonDirection, directionSoleil);
        couleurFinal = mix(couleurFinal, couleurBrouillard, facteurBrouillard);
    } else {
        couleurFinal = couleurCiel(rayonDirection, directionSoleil);
    }

    couleurFinal = mix(couleurFinal, vec3(1.0, 0.6, 0.3), intensiteChaleur * 0.15);

    couleurFinal = pow(couleurFinal, vec3(0.4545));

    couleurFragment = vec4(couleurFinal, 1.0);
}
